window.MG_LAZY_DATA["data/lazy/courses/d107-274ad48aadc74ba8.json"]={sha256:"274ad48aadc74ba8428b4f2342b9f586238fd2b55acb3cfbe1468417654dbf41",value:{"id":"d107","title":"呂勒奧HYBRIT試驗工程","titleEn":"Lulea HYBRIT Pilot Engineering","category":"materials","kind":"course","summary":"以呂勒奧試驗設施理解氫還原、製氫、儲存與材料證據的系統關係。","summaryEn":"Use the Luleå pilots to understand hydrogen reduction, electrolysis, storage and material evidence as connected systems.","scope":"以公開試驗原理與紙上物料帳進行十二個概念任務。呂勒奧為試驗設施；耶利瓦勒的工業示範規劃為另一地點與尺度。本課不含化學製備、氫氣設備建造、操作參數或完整量產 SOP。","scopeEn":"Twelve conceptual tasks use public pilot principles and paper material accounts. Luleå hosts pilots; the Gällivare industrial-demonstration plan is a different site and scale. No chemical preparation, hydrogen equipment construction, operating settings or complete production SOP is provided.","contentStatus":"reviewable-educational-curriculum","sourceIds":["v6-science-hybrit-milestones","v6-science-hybrit-reduction","v6-science-hybrit-storage"],"depth":4,"diagram":{"type":"materials","labels":["礦石球團","電解製氫","直接還原","儲存緩衝","產品證據"],"labelsEn":["Ore pellets","Electrolysis","Direct reduction","Storage buffer","Product evidence"],"original":true,"notToScale":true},"stages":[{"id":"d107-stage01","order":1,"title":"試驗邊界與投入","titleEn":"Pilot boundaries and inputs","description":"分清設施成熟度、物料與能源投入。","descriptionEn":"Separate facility maturity, material inputs and energy inputs.","route":"依學習相依關係閱讀；這四步是公開原理的概念任務，不是現場施工、操作或量產程序。","routeEn":"Follow the learning dependencies. These four tasks explore public principles; they are not field, operating or production procedures.","steps":[{"id":"d107-v6-01","order":1,"sequence":1,"prerequisiteIds":[],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hybrit-milestones","v6-science-hybrit-storage"],"title":"區分試驗與工業示範邊界","titleEn":"Separate pilot and industrial demonstration boundaries","objective":"分清呂勒奧試驗設施與耶利瓦勒工業示範規劃。","objectiveEn":"Distinguish the Luleå pilots from the planned Gällivare industrial demonstration.","instruction":"將呂勒奧還原試驗、呂勒奧儲氫試驗、耶利瓦勒示範規劃三張卡按地點與成熟度分類。","instructionEn":"Sort Luleå reduction, Luleå storage and planned Gällivare demonstration cards by location and maturity.","observation":"一項技術可以在不同城市、不同規模分階段驗證。","observationEn":"One technology can undergo staged verification at different scales and locations.","failure":"將試驗成功直接等同商業量產，會遺漏放大與整合的證據。","failureEn":"Equating pilot success with commercial production omits scale-up and integration evidence.","check":"每張卡均列地點、年份與已驗證的範圍，規劃不標為完工。","checkEn":"Give each card a location, date and verified scope; do not label plans as completed.","knowledge":[{"id":"d107-v6-01-k1","title":"工程原理","titleEn":"Engineering principle","text":"試驗設施與工業示範的設備尺度和證據範圍不同。","textEn":"Pilot and industrial-demonstration facilities differ in scale and evidential scope."},{"id":"d107-v6-01-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本課以呂勒奧公開試驗原理為案例，不宣稱耶利瓦勒設施已完工。","textEn":"This course uses public Luleå pilot principles without claiming completion at Gällivare."}],"quiz":{"question":"哪個分類符合官方地點區分？","questionEn":"Which classification follows the official location distinction?","options":["呂勒奧是試驗案例，耶利瓦勒是另項示範規劃","三張卡均代表同一座已量產工廠","只要名稱相近就不需地點證據"],"optionsEn":["Luleå is the pilot case; Gällivare is a separate demonstration plan","All three cards represent one operating commercial factory","Similar names remove the need for location evidence"],"answer":0,"explanation":"試驗設施與工業示範的設備尺度和證據範圍不同。 本課以呂勒奧公開試驗原理為案例，不宣稱耶利瓦勒設施已完工。","explanationEn":"Pilot and industrial-demonstration facilities differ in scale and evidential scope. This course uses public Luleå pilot principles without claiming completion at Gällivare."}},{"id":"d107-v6-02","order":2,"sequence":2,"prerequisiteIds":["d107-v6-01"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hybrit-reduction"],"title":"追蹤礦石中的鐵與氧","titleEn":"Track iron and oxygen in the ore","objective":"把還原反應理解為移除氧而保留鐵的物料變化。","objectiveEn":"Understand reduction as oxygen removal while retaining iron.","instruction":"用紙卡表示鐵、氧與氫，把反應前後的元素分別對帳；不配置化學品。","instructionEn":"Represent iron, oxygen and hydrogen with paper cards and balance each element before and after reaction; use no chemicals.","observation":"產物的鐵與被帶走的氧都有對應來源。","observationEn":"Both product iron and removed oxygen have identifiable origins.","failure":"只比較總質量而忽略含氧量，會把失重誤當鐵流失。","failureEn":"Comparing total mass without oxygen content can mistake oxygen removal for lost iron.","check":"各元素卡片數量守恆，並把水標在產物側。","checkEn":"Conserve the count of each element and place water on the product side.","knowledge":[{"id":"d107-v6-02-k1","title":"工程原理","titleEn":"Engineering principle","text":"氫還原鐵氧化物時，氧與氫形成水。","textEn":"During hydrogen reduction of iron oxide, oxygen combines with hydrogen to form water."},{"id":"d107-v6-02-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"紙卡表達元素守恆，不提供實際反應條件或氣體配比。","textEn":"Cards express elemental conservation, not reaction conditions or gas-mixture recipes."}],"quiz":{"question":"還原後少掉的氧應如何交代？","questionEn":"How should removed oxygen be accounted for?","options":["當作質量憑空消失","追蹤到含氧產物流，例如水","假定所有失重都是鐵被消耗"],"optionsEn":["Treat it as mass that vanished","Trace it into an oxygen-containing product such as water","Assume all mass loss is consumed iron"],"answer":1,"explanation":"氫還原鐵氧化物時，氧與氫形成水。 紙卡表達元素守恆，不提供實際反應條件或氣體配比。","explanationEn":"During hydrogen reduction of iron oxide, oxygen combines with hydrogen to form water. Cards express elemental conservation, not reaction conditions or gas-mixture recipes."}},{"id":"d107-v6-03","order":3,"sequence":3,"prerequisiteIds":["d107-v6-02"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hybrit-reduction"],"title":"比較球團孔隙與反應介面","titleEn":"Compare pellet porosity and reaction interfaces","objective":"理解固體形狀與氣體接觸路徑的關係。","objectiveEn":"Relate solid structure to gas-access paths.","instruction":"畫兩個同外徑的概念球團剖面，一個連通孔隙較多、一個孔隙封閉；標示可接觸區。","instructionEn":"Draw two equal-diameter conceptual pellets, one with connected pores and one with closed pores; mark accessible regions.","observation":"外徑相同的球團未必具有相同內部可接觸面。","observationEn":"Equal external diameters do not imply equal internal accessibility.","failure":"只看外形就推定還原程度一致，會忽略傳質差異。","failureEn":"Inferring equal reduction from appearance ignores mass-transfer differences.","check":"明確區分外部尺寸、孔隙連通性與尚未量測的內部狀態。","checkEn":"Distinguish external dimensions, pore connectivity and unmeasured internal condition.","knowledge":[{"id":"d107-v6-03-k1","title":"工程原理","titleEn":"Engineering principle","text":"固體內部的傳質路徑影響反應物能否抵達反應介面。","textEn":"Internal transport paths influence whether reactants reach reaction interfaces."},{"id":"d107-v6-03-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"示意圖只能提出假說，真實球團性能需適用量測與材料資料。","textEn":"A sketch proposes a hypothesis; real pellet performance needs suitable measurements and material data."}],"quiz":{"question":"哪個推論最可靠？","questionEn":"Which inference is most defensible?","options":["相同外徑保證完全相同的還原表現","孔隙圖足以取代所有材料驗證","相同外徑仍可能具有不同氣體可達性"],"optionsEn":["Equal diameters guarantee identical reduction performance","A pore sketch replaces all material verification","Equal diameters can still have different gas accessibility"],"answer":2,"explanation":"固體內部的傳質路徑影響反應物能否抵達反應介面。 示意圖只能提出假說，真實球團性能需適用量測與材料資料。","explanationEn":"Internal transport paths influence whether reactants reach reaction interfaces. A sketch proposes a hypothesis; real pellet performance needs suitable measurements and material data."}},{"id":"d107-v6-04","order":4,"sequence":4,"prerequisiteIds":["d107-v6-03"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hybrit-reduction"],"title":"標示製氫的能源與水介面","titleEn":"Mark electricity and water interfaces for hydrogen","objective":"區分電解的物料投入與能源投入。","objectiveEn":"Separate material inputs from energy inputs in electrolysis.","instruction":"畫水與電力進入電解方塊、氫與氧離開的流程；把電力畫成能量箭頭。","instructionEn":"Draw water and electricity entering an electrolysis block and hydrogen and oxygen leaving; use an energy arrow for electricity.","observation":"電力供應來源會影響整體能源與排放評估。","observationEn":"The electricity source affects the overall energy and emissions assessment.","failure":"把電力寫成反應物質量，會混淆能量帳與物料帳。","failureEn":"Recording electricity as reactant mass confuses energy and material accounts.","check":"為水、氫、氧使用物料單位，為電力使用功率或電量單位。","checkEn":"Use material units for water, hydrogen and oxygen, and power or energy units for electricity.","knowledge":[{"id":"d107-v6-04-k1","title":"工程原理","titleEn":"Engineering principle","text":"電解需要外部能量，不能僅由水的質量推算完整能耗。","textEn":"Electrolysis requires external energy; water mass alone cannot determine total energy demand."},{"id":"d107-v6-04-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"課程不含自製電解設備、氣體收集或通電操作。","textEn":"The course includes no homemade electrolyzer, gas collection or energization procedure."}],"quiz":{"question":"哪組資訊應放在不同帳表？","questionEn":"Which information belongs in separate accounts?","options":["水的質量與用電量","兩次以同單位量得的水質量","同一時間窗的氫氣投入與產出"],"optionsEn":["Water mass and electricity consumption","Two water masses measured in the same units","Hydrogen input and output over one time window"],"answer":0,"explanation":"電解需要外部能量，不能僅由水的質量推算完整能耗。 課程不含自製電解設備、氣體收集或通電操作。","explanationEn":"Electrolysis requires external energy; water mass alone cannot determine total energy demand. The course includes no homemade electrolyzer, gas collection or energization procedure."}}]},{"id":"d107-stage02","order":2,"title":"還原與循環介面","titleEn":"Reduction and recycle interfaces","description":"追蹤氧、水、固體產品與熱收支。","descriptionEn":"Trace oxygen, water, solid products and heat accounts.","route":"依學習相依關係閱讀；這四步是公開原理的概念任務，不是現場施工、操作或量產程序。","routeEn":"Follow the learning dependencies. These four tasks explore public principles; they are not field, operating or production procedures.","steps":[{"id":"d107-v6-05","order":1,"sequence":5,"prerequisiteIds":["d107-v6-04"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hybrit-milestones","v6-science-hybrit-reduction"],"title":"比較氫還原的流程邊界","titleEn":"Compare the hydrogen-reduction process boundary","objective":"避免把局部反應與全生命週期排放混同。","objectiveEn":"Avoid confusing a local reaction with lifecycle emissions.","instruction":"畫氫直接還原與以碳作還原劑的概念路徑；另列電力、礦石與運輸的上游欄。","instructionEn":"Sketch hydrogen and carbon-reductant routes and add upstream electricity, ore and transport columns.","observation":"反應出口的差異不會自動消除上游影響。","observationEn":"Differences at the reaction outlet do not automatically eliminate upstream impacts.","failure":"只看水蒸氣出口就宣稱任何電源皆零排放，會越過證據邊界。","failureEn":"Claiming zero emissions for any electricity source from a water outlet exceeds the evidence.","check":"結論標明局部製程或生命週期邊界，不把二者混寫。","checkEn":"Label conclusions as process-level or lifecycle-level and keep the boundaries distinct.","knowledge":[{"id":"d107-v6-05-k1","title":"工程原理","titleEn":"Engineering principle","text":"直接還原路徑的反應產物與能源供應排放需分開核算。","textEn":"Reaction products and energy-supply emissions require separate accounting."},{"id":"d107-v6-05-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"官方化石燃料替代目標不是本課自行計算出的完整碳盤查結果。","textEn":"Official fossil-fuel replacement goals are not a lifecycle inventory calculated by this lesson."}],"quiz":{"question":"哪個主張需要額外上游資料？","questionEn":"Which claim requires additional upstream data?","options":["氫還原能形成水","全生命週期排放為零","電解需要電力"],"optionsEn":["Hydrogen reduction can form water","Lifecycle emissions are zero","Electrolysis needs electricity"],"answer":1,"explanation":"直接還原路徑的反應產物與能源供應排放需分開核算。 官方化石燃料替代目標不是本課自行計算出的完整碳盤查結果。","explanationEn":"Reaction products and energy-supply emissions require separate accounting. Official fossil-fuel replacement goals are not a lifecycle inventory calculated by this lesson."}},{"id":"d107-v6-06","order":2,"sequence":6,"prerequisiteIds":["d107-v6-05"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hybrit-reduction"],"title":"追蹤回流氣與水分離","titleEn":"Trace gas recirculation and water separation","objective":"識別循環物流及其累積項。","objectiveEn":"Identify recycle streams and accumulation terms.","instruction":"在概念圖把反應後氣流接到水分離方塊，再畫回流與補充物流；所有數值留白待證據填入。","instructionEn":"Connect reactor outlet gas to a water-separation block, then draw recycle and make-up streams; leave values blank pending evidence.","observation":"回流可以重用未反應物，但不等同沒有損失。","observationEn":"Recycle can reuse unreacted material but does not imply zero losses.","failure":"把回流當新的外部投入重複相加，會高估資源使用。","failureEn":"Counting recycle again as external input overstates resource use.","check":"分別圈出整廠邊界與回流迴路，確認每條外部物流只記一次。","checkEn":"Circle plant and recycle boundaries separately and count each external stream once.","knowledge":[{"id":"d107-v6-06-k1","title":"工程原理","titleEn":"Engineering principle","text":"循環製程的總帳與單元帳具有不同邊界。","textEn":"Overall and unit-level accounts use different boundaries in a recycle process."},{"id":"d107-v6-06-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本圖只表達流程邏輯，不提供分離器設計或氫氣操作條件。","textEn":"The diagram expresses process logic, not separator design or hydrogen operating conditions."}],"quiz":{"question":"整廠資源帳中應如何處理內部回流？","questionEn":"How should internal recycle appear in a plant-wide resource account?","options":["每循環一次都算全新外購量","認定有回流就不會有損失","不重複算成新的外部供應"],"optionsEn":["Count every pass as new purchased supply","Assume recycle eliminates all losses","Do not count it again as new external supply"],"answer":2,"explanation":"循環製程的總帳與單元帳具有不同邊界。 本圖只表達流程邏輯，不提供分離器設計或氫氣操作條件。","explanationEn":"Overall and unit-level accounts use different boundaries in a recycle process. The diagram expresses process logic, not separator design or hydrogen operating conditions."}},{"id":"d107-v6-07","order":3,"sequence":7,"prerequisiteIds":["d107-v6-06"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hybrit-reduction"],"title":"區分海綿鐵與完成鋼品","titleEn":"Distinguish sponge iron from finished steel","objective":"辨識直接還原產物與後續熔煉的介面。","objectiveEn":"Identify the interface between direct-reduced material and downstream steelmaking.","instruction":"將鐵礦球團、海綿鐵、後續熔煉與鋼品四張卡排序；在海綿鐵旁標固體與多孔。","instructionEn":"Order ore pellet, sponge iron, downstream melting and steel-product cards; mark sponge iron as solid and porous.","observation":"取得金屬鐵不代表合金成分與最終形狀已完成。","observationEn":"Producing metallic iron does not finish alloy composition or final shape.","failure":"把還原產物直接標為完成鋼材，會略過下游品質需求。","failureEn":"Labelling reduced material as finished steel skips downstream quality requirements.","check":"在兩個製程間列成分、物理狀態與可追溯批次三項交接資料。","checkEn":"List composition, physical state and traceable batch as three handover fields.","knowledge":[{"id":"d107-v6-07-k1","title":"工程原理","titleEn":"Engineering principle","text":"直接還原可在不熔化鐵的條件下形成海綿鐵。","textEn":"Direct reduction can form sponge iron without melting the iron."},{"id":"d107-v6-07-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本課沒有鋼廠配料或熔煉程序，僅辨識產品階段。","textEn":"This course identifies product stages without steelmaking recipes or melting procedures."}],"quiz":{"question":"海綿鐵卡應放在哪裡？","questionEn":"Where does the sponge-iron card belong?","options":["直接還原之後、後續鋼品製造之前","最終塗裝包裝之後","取代整個鋼材品質驗證程序"],"optionsEn":["After direct reduction and before downstream steel production","After final coating and packaging","In place of the entire steel-quality verification process"],"answer":0,"explanation":"直接還原可在不熔化鐵的條件下形成海綿鐵。 本課沒有鋼廠配料或熔煉程序，僅辨識產品階段。","explanationEn":"Direct reduction can form sponge iron without melting the iron. This course identifies product stages without steelmaking recipes or melting procedures."}},{"id":"d107-v6-08","order":4,"sequence":8,"prerequisiteIds":["d107-v6-07"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hybrit-reduction"],"title":"分離熱需求與化學轉化","titleEn":"Separate heat demand from chemical conversion","objective":"理解反應完成度與熱收支是不同檢查。","objectiveEn":"Understand reaction completion and heat balance as separate checks.","instruction":"畫物料流和熱流兩層圖；把加熱、散熱與熱回收放入能量層，不填實際溫度。","instructionEn":"Draw material-flow and heat-flow layers; place heating, losses and recovery in the energy layer without assigning real temperatures.","observation":"同一物料路線可以因熱損失而有不同外部能源需求。","observationEn":"The same material route can require different external energy because of heat losses.","failure":"只有元素守恆就宣稱能源足夠，會漏掉熱需求。","failureEn":"Declaring energy sufficiency from elemental balance alone omits heat demand.","check":"每一個熱流都有方向，回收熱不重複計作新供應。","checkEn":"Give each heat flow a direction and avoid counting recovered heat as new supply twice.","knowledge":[{"id":"d107-v6-08-k1","title":"工程原理","titleEn":"Engineering principle","text":"物料守恆與能量守恆必須各自閉合。","textEn":"Material and energy conservation must each close independently."},{"id":"d107-v6-08-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"沒有完整設備資料時，只能列需求項與未知量。","textEn":"Without complete equipment data, the result can only list requirements and unknowns."}],"quiz":{"question":"哪份證據不能單獨證明熱收支閉合？","questionEn":"Which evidence alone cannot establish a closed heat balance?","options":["完整且同邊界的能量帳","元素數量守恆表","帶單位的熱輸入與損失核對"],"optionsEn":["A complete energy account with consistent boundaries","An elemental conservation table","A unit-labelled comparison of heat input and losses"],"answer":1,"explanation":"物料守恆與能量守恆必須各自閉合。 沒有完整設備資料時，只能列需求項與未知量。","explanationEn":"Material and energy conservation must each close independently. Without complete equipment data, the result can only list requirements and unknowns."}}]},{"id":"d107-stage03","order":3,"title":"時間緩衝與證據交接","titleEn":"Time buffering and evidence handover","description":"以庫存模型與批次證據審視整合。","descriptionEn":"Review integration through inventory models and batch evidence.","route":"依學習相依關係閱讀；這四步是公開原理的概念任務，不是現場施工、操作或量產程序。","routeEn":"Follow the learning dependencies. These four tasks explore public principles; they are not field, operating or production procedures.","steps":[{"id":"d107-v6-09","order":1,"sequence":9,"prerequisiteIds":["d107-v6-08"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hybrit-storage"],"title":"建立儲氫庫存的概念帳","titleEn":"Build a conceptual hydrogen inventory account","objective":"理解儲存如何緩衝產需時間差。","objectiveEn":"Understand how storage buffers timing differences between supply and demand.","instruction":"使用假設庫存 5、同時段流入 4、流出 3 個抽象單位，計算期末庫存。","instructionEn":"Use assumed inventory 5, inflow 4 and outflow 3 abstract units over one period to calculate ending inventory.","observation":"期末為 6 單位，儲存改變供應時間而非製造額外氫。","observationEn":"Ending inventory is 6 units; storage changes supply timing rather than creating hydrogen.","failure":"把充入量當作淨庫存增加會漏算同期取用。","failureEn":"Treating inflow as net inventory growth omits simultaneous withdrawal.","check":"驗證期初加流入減流出等於期末，並保留假設標籤。","checkEn":"Check opening plus inflow minus outflow against closing inventory and retain assumption labels.","knowledge":[{"id":"d107-v6-09-k1","title":"工程原理","titleEn":"Engineering principle","text":"儲存設備連接製氫供給與還原需求的時間尺度。","textEn":"Storage connects the time scales of hydrogen supply and reduction demand."},{"id":"d107-v6-09-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"抽象單位不是壓力、容量設計或儲氫操作建議。","textEn":"Abstract units are not pressure settings, capacity designs or storage operating advice."}],"quiz":{"question":"假設期末庫存是多少？","questionEn":"What is the assumed ending inventory?","options":["9 個抽象單位","2 個抽象單位","6 個抽象單位"],"optionsEn":["9 abstract units","2 abstract units","6 abstract units"],"answer":2,"explanation":"儲存設備連接製氫供給與還原需求的時間尺度。 抽象單位不是壓力、容量設計或儲氫操作建議。","explanationEn":"Storage connects the time scales of hydrogen supply and reduction demand. Abstract units are not pressure settings, capacity designs or storage operating advice."}},{"id":"d107-v6-10","order":2,"sequence":10,"prerequisiteIds":["d107-v6-09"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hybrit-storage"],"title":"比較兩段供需時間曲線","titleEn":"Compare supply and demand over two periods","objective":"區分平均供需平衡與每時段可供性。","objectiveEn":"Distinguish average balance from availability in each period.","instruction":"假設兩時段供應為 8、2，需求為 5、5；從零庫存開始，以紙上帳記錄可轉移的餘量。","instructionEn":"Assume supply of 8 and 2 and demand of 5 and 5 across two periods; track transferable surplus from zero opening inventory.","observation":"第一段餘量 3 可以在理想無損概念模型中補第二段缺口 3。","observationEn":"A surplus of 3 can fill the later deficit of 3 in an ideal lossless concept model.","failure":"只看總量 10 等於 10 就忽略時序，會錯判無儲存情況也可連續供應。","failureEn":"Looking only at equal totals of 10 misses timing and falsely implies continuous supply without storage.","check":"比較有儲存與無儲存兩張表，寫明模型忽略容量及速率限制。","checkEn":"Compare accounts with and without storage and state that the model omits capacity and rate limits.","knowledge":[{"id":"d107-v6-10-k1","title":"工程原理","titleEn":"Engineering principle","text":"平均平衡不能保證每個時間窗皆平衡。","textEn":"Average balance does not guarantee balance in every time window."},{"id":"d107-v6-10-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"實際儲存還有損失、充放速率、容量與專業安全限制。","textEn":"Real storage also has losses, transfer-rate, capacity and professionally assessed safety limits."}],"quiz":{"question":"為何總供應等於總需求仍可能短缺？","questionEn":"Why can shortages occur despite equal total supply and demand?","options":["供需發生時間不同且缺少可用緩衝","守恆定律因此失效","只要總量相同就永遠不會短缺"],"optionsEn":["Supply and demand occur at different times without available buffering","Conservation therefore fails","Equal totals always eliminate shortages"],"answer":0,"explanation":"平均平衡不能保證每個時間窗皆平衡。 實際儲存還有損失、充放速率、容量與專業安全限制。","explanationEn":"Average balance does not guarantee balance in every time window. Real storage also has losses, transfer-rate, capacity and professionally assessed safety limits."}},{"id":"d107-v6-11","order":3,"sequence":11,"prerequisiteIds":["d107-v6-10"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hybrit-milestones","v6-science-hybrit-reduction"],"title":"設計批次證據與材料交接","titleEn":"Design batch evidence and material handover","objective":"把材料身份與品質聲明連接到證據。","objectiveEn":"Link material identity and quality claims to evidence.","instruction":"製作虛構批次卡，列原料批號、還原產品身份、檢驗方法引用與未驗證欄。","instructionEn":"Create a fictional batch card with feed ID, reduced-product identity, test-method reference and unverified fields.","observation":"沒有批號的數據無法可靠連回特定材料。","observationEn":"Data without a batch identity cannot reliably be linked to a particular material.","failure":"將別批次數值複製成當批驗證，會破壞可追溯性。","failureEn":"Copying another batch’s values as current verification breaks traceability.","check":"所有數值標為自設示例或附來源，不把空欄當通過。","checkEn":"Label every value as hypothetical or sourced, and do not treat blanks as passes.","knowledge":[{"id":"d107-v6-11-k1","title":"工程原理","titleEn":"Engineering principle","text":"批次追溯把原料、處理歷史與產品證據連為一體。","textEn":"Batch traceability links feedstock, processing history and product evidence."},{"id":"d107-v6-11-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本課不設定商業鋼材驗收規格；接受條件需由適用標準與買方定義。","textEn":"The lesson sets no commercial steel acceptance specification; applicable standards and buyers define those conditions."}],"quiz":{"question":"檢驗欄空白時，最適合的狀態為何？","questionEn":"What is the appropriate status for a blank test field?","options":["自動通過","尚未驗證","以其他批次最高分代替"],"optionsEn":["Automatically passed","Not yet verified","Replace it with the highest score from another batch"],"answer":1,"explanation":"批次追溯把原料、處理歷史與產品證據連為一體。 本課不設定商業鋼材驗收規格；接受條件需由適用標準與買方定義。","explanationEn":"Batch traceability links feedstock, processing history and product evidence. The lesson sets no commercial steel acceptance specification; applicable standards and buyers define those conditions."}},{"id":"d107-v6-12","order":4,"sequence":12,"prerequisiteIds":["d107-v6-11"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hybrit-milestones","v6-science-hybrit-reduction","v6-science-hybrit-storage"],"title":"審查試驗工程的放大證據","titleEn":"Review evidence for pilot scale-up","objective":"完成區分已證實、假設與待驗證的系統交接。","objectiveEn":"Complete a handover distinguishing demonstrated facts, assumptions and open verification.","instruction":"提交地點成熟度表、物料與能量圖、儲存兩時段帳，以及三項放大後需再驗證的介面。","instructionEn":"Submit the location/maturity table, material and energy diagrams, two-period storage account and three interfaces needing scale-up verification.","observation":"放大問題包含傳熱、傳質、連續性與供應介面的共同變化。","observationEn":"Scale-up involves coupled changes in heat transfer, mass transfer, continuity and supply interfaces.","failure":"把小規模證據直接當成所有尺度保證，會超出資料支援範圍。","failureEn":"Treating small-scale evidence as a guarantee at every scale exceeds its support.","check":"逐句標註已證實、教學假設或待查證，並保留來源日期。","checkEn":"Label each claim as demonstrated, teaching assumption or unverified, retaining source dates.","knowledge":[{"id":"d107-v6-12-k1","title":"工程原理","titleEn":"Engineering principle","text":"工程成熟度依賴可轉移的證據，而非僅依賴項目名稱。","textEn":"Engineering maturity depends on transferable evidence, not the project name alone."},{"id":"d107-v6-12-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"完成十二步代表概念審查，不代表完成氫系統設計或商業生產認證。","textEn":"Completing twelve tasks is a conceptual review, not hydrogen-system design or commercial-production certification."}],"quiz":{"question":"哪個交接最能避免誇大試驗成果？","questionEn":"Which handover best avoids overstating pilot results?","options":["只寫技術已完全成熟","刪除地點與年份以免比較","明列規模、邊界與尚需驗證的介面"],"optionsEn":["State only that the technology is fully mature","Remove locations and dates to prevent comparison","State scale, boundaries and interfaces still requiring verification"],"answer":2,"explanation":"工程成熟度依賴可轉移的證據，而非僅依賴項目名稱。 完成十二步代表概念審查，不代表完成氫系統設計或商業生產認證。","explanationEn":"Engineering maturity depends on transferable evidence, not the project name alone. Completing twelve tasks is a conceptual review, not hydrogen-system design or commercial-production certification."}}]}],"status":"guided","languageCoverage":["zh-TW","en"],"curriculumVersion":6,"stepCount":12,"estimatedMinutes":240}};
